def countRoutesOneWall(grid):
    MOD = 10 ** 9 + 7
    m, n = len(grid), len(grid[0])
    cur = [[0, 0] for _ in range(n)]
    for r in range(m):
        for c in range(n):
            if r == 0 and c == 0:
                a, b = 1, 0
            else:
                a = b = 0
                if r > 0:
                    a += cur[c][0]
                    b += cur[c][1]
                if c > 0:
                    a += cur[c - 1][0]
                    b += cur[c - 1][1]
            if grid[r][c] == 1:
                a, b = 0, a
            cur[c] = [a % MOD, b % MOD]
    return (cur[n - 1][0] + cur[n - 1][1]) % MOD
